import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        while (scanner.hasNext()) {
            String str = scanner.next();
            StringBuilder output = new StringBuilder();
            output.append(str.charAt(0));
            int replacedAt = 0;
            for (int index = 1; index < str.length(); index++) {
                if (replacedAt == 0 && str.charAt(index) == 'a' && index + 1 < str.length() && str.charAt(index + 1) == 't') {
                    output.append('@');
                    replacedAt = 1;
                    index++;
                    continue;
                }
                if (index + 2 < str.length() && str.charAt(index) == 'd' && str.charAt(index + 1) == 'o' && str.charAt(index + 2) == 't') {
                    output.append('.');
                    index += 2;
                    continue;
                }
                output.append(str.charAt(index));
            }
            System.out.println(output.toString());
        }
        scanner.close();
    }
}
